sys_script_include.script:
var Hoc_CotlUtilsAjax = Class.create();
Hoc_CotlUtilsAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    checkcheckliststatut: function() {
        result = true;
        var uniqueid = this.getParameter('sysparm_uniqueid');
        var ci = new GlideRecord('checklist_item');
        ci.addQuery('checklist.document', uniqueid);
        ci.addQuery('complete', false);
        ci.query(); // 
        if (ci.next()) {
            gs.addErrorMessage('All checklist items must be completed before submission.');
            result = false;
        }

        return result;

    },

    checktaskstatut: function() {
        result = true;
        var uniquesysid = this.getParameter('sysparm_uniquesysid');
        var cotltask = new GlideRecord('x_hccc_cotl_task');
        cotltask.addEncodedQuery('worksheet=' + uniquesysid + "^state!=3");
        cotltask.query(); // 
        if (cotltask.next()) {
            result = false;
        }

        return result;

    },

    getparent: function() {
        var requestedfor = this.getParameter('sysparm_requestedfor');
        var user = new GlideRecord('sys_user');
        user.get(requestedfor);
        return user.x_hccc_base_pbdata_member_profile.caucus.parent;

    },

    checkFieldValue: function(tasktype) {
        var parentId = this.getParameter('sysparm_parentfield');
        var parent = new GlideRecord('x_hccc_cotl_worksheet');
        if (!parent.get(parentId)) {
            gs.info("Parent non trouvé");
            return;
        }

        var howMuch = parseInt(parent.getValue('how_many_computers'), 10);
        if (isNaN(howMuch)) {
            gs.info("how_much_computer invalide");
            return;
        }

        var cotlTask = new GlideRecord('x_hccc_cotl_task');
        cotlTask.addQuery('worksheet', parentId);
        cotlTask.addQuery('task_type', 'computer');
        cotlTask.query();

        var filledFields = [];

        while (cotlTask.next()) {
            for (var i = 1; i <= howMuch; i++) {
                var fieldName = 'computer_' + i;
                var val = cotlTask.getValue(fieldName);
                if (val) {
                    filledFields.push(fieldName);
                }
            }
        }
        var toShow = [];
        for (var j = 1; j <= howMuch; j++) {
            var field = 'computer_' + j;
            if (filledFields.indexOf(field) === -1) {
                toShow.push(field);
            }
        }
        // gs.addErrorMessage("Champs computer à afficher : " + toShow.join(', '));
        // gs.addErrorMessage('champs readonly' + filledFields);
        // gs.addErrorMessage('champs editable' + toShow);


        return JSON.stringify({
            readonly: filledFields,
            editable: toShow
        });
    },

	checkFieldValuedocking: function(tasktype) {
        var parentId = this.getParameter('sysparm_parentfield');
        var parent = new GlideRecord('x_hccc_cotl_worksheet');
        if (!parent.get(parentId)) {
            gs.info("Parent non trouvé");
            return;
        }

        var howMuch = parseInt(parent.getValue('how_many_docking_monitors_are_requested_for_this_site'), 10);
        if (isNaN(howMuch)) {
            gs.info("how_many_docking_monitors_are_requested_for_this_site invalide");
            return;
        }

        var cotlTask = new GlideRecord('x_hccc_cotl_task');
        cotlTask.addQuery('worksheet', parentId);
        cotlTask.addQuery('task_type', 'computer');
        cotlTask.query();

        var filledFields = [];

        while (cotlTask.next()) {
            for (var i = 1; i <= howMuch; i++) {
                var fieldName = 'docking_' + i;
                var val = cotlTask.getValue(fieldName);
                if (val) {
                    filledFields.push(fieldName);
                }
            }
        }
        var toShow = [];
        for (var j = 1; j <= howMuch; j++) {
            var field = 'docking_' + j;
            if (filledFields.indexOf(field) === -1) {
                toShow.push(field);
            }
        }
        // gs.addErrorMessage("Champs docking à afficher : " + toShow.join(', '));
        // gs.addErrorMessage('champs docking readonly' + filledFields);
        // gs.addErrorMessage('champs docking  editable' + toShow);


        return JSON.stringify({
            readonly: filledFields,
            editable: toShow
        });
    },

    type: 'Hoc_CotlUtilsAjax'
});
